// Idempotency: prevent duplicate weekly digest emails for the same Monday.
// Key format: weekly_var_digest:YYYY-MM-DD  Lifecycle: processing → sent.
// Stale 'processing' (>30 min) allows retry.
const now = new Date();

const parts = new Intl.DateTimeFormat('fr-FR', {
  timeZone: 'Europe/Paris',
  year: 'numeric', month: '2-digit', day: '2-digit'
}).formatToParts(now);
const year  = parts.find(p => p.type === 'year').value;
const month = parts.find(p => p.type === 'month').value;
const day   = parts.find(p => p.type === 'day').value;
const dateKey  = `${year}-${month}-${day}`;
const digestKey = `weekly_var_digest:${dateKey}`;

const staticData = $getWorkflowStaticData('global');
if (!staticData.sentDigests) staticData.sentDigests = {};

const entry = staticData.sentDigests[digestKey];
if (entry) {
  if (entry.status === 'sent') {
    return [{ json: { skip: true, reason: 'already_sent', key: digestKey } }];
  }
  if (entry.status === 'processing') {
    const ageMs = Date.now() - new Date(entry.ts).getTime();
    if (ageMs < 30 * 60 * 1000) {
      return [{ json: { skip: true, reason: 'already_processing', key: digestKey } }];
    }
    // Stale processing (>30 min) — previous attempt likely failed. Allow retry.
  }
}

staticData.sentDigests[digestKey] = { status: 'processing', ts: now.toISOString() };

// Trim to last 52 weeks.
const entries = Object.entries(staticData.sentDigests);
if (entries.length > 52) {
  staticData.sentDigests = Object.fromEntries(
    entries.sort((a, b) => a[0].localeCompare(b[0])).slice(-52)
  );
}

return [{ json: { skip: false, digest_key: digestKey, date_label: dateKey } }];

// Format Digest — GLOBAL Top-N ranking (Location Priority feature, 2026-09-10).
// Input: HTTP response from /api/jobs/digest/weekly-combined:
//   { run_id, run_completed_at, run_age_hours, top_jobs: [WeeklyDigestJobOut...], ... }
// top_jobs is a single global ranking by score, independent of department/remote —
// deliberately NOT sectioned by location. Discord's real-time channels already
// cover "best jobs per preferred location"; this weekly email is the broader,
// complementary "best overall opportunities this week" surface.
const response = $input.first().json;
const topJobs = Array.isArray(response.top_jobs) ? response.top_jobs : [];
const runAgeHours    = response.run_age_hours || 0;
const runCompletedAt = (response.run_completed_at || '').slice(0, 19).replace('T', ' ');
const runId          = (response.run_id || '').slice(0, 8);

const idempotencyData = $('Check Idempotency').first().json;
const dateLabel = idempotencyData.date_label || new Date().toISOString().slice(0, 10);
const digestKey = idempotencyData.digest_key;

const [y, m, d] = dateLabel.split('-');
const monthNames = ['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
const formattedDate = `lundi ${parseInt(d)} ${monthNames[parseInt(m) - 1]} ${y}`;

// Phase 5 (2026-09-10): reads the CANONICAL tier the backend already computed
// (score_to_tier, via GET /api/jobs/digest/weekly-combined's `tier` field)
// instead of keeping a second, score-threshold-based copy here that could
// drift out of sync — see src/pipeline/scoring.py's _TIER_THRESHOLDS.
const TIER_EMOJI = { exceptional: '🔥', excellent: '⭐', strong: '👍', relevant: '📋', low_priority: '🗄️' };
const tierEmoji = (tier) => TIER_EMOJI[tier] || '🗄️';
const rankEmoji = (r) => ({ 1: '🥇', 2: '🥈', 3: '🥉' }[r] || `#${r}`);
const esc = (s) => s ? String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;') : '';
const modeLabel = (j) => {
  if (j.remote) return 'Télétravail complet';
  return { remote: 'Télétravail', hybrid: 'Hybride', on_site: 'Présentiel' }[j.work_mode] || j.work_mode || 'Non précisé';
};

const jobCard = (j) => {
  const url   = j.canonical_url || j.apply_url || '';
  const skills = (j.skills || []).join(' · ') || '—';
  const link  = url
    ? `<a href="${esc(url)}" style="display:inline-block;padding:6px 14px;background:#2563EB;color:#fff;text-decoration:none;border-radius:4px;font-size:13px;font-weight:600;" target="_blank">Voir l'offre →</a>`
    : '<span style="color:#9CA3AF;font-size:13px;">Lien non disponible</span>';
  const scoreColor = j.score_100 >= 80 ? '#059669' : j.score_100 >= 60 ? '#D97706' : '#6B7280';
  return `
    <div style="background:#fff;border:1px solid #E5E7EB;border-radius:8px;padding:18px 22px;margin-bottom:14px;">
      <div style="display:flex;align-items:baseline;gap:8px;margin-bottom:3px;">
        <span style="font-size:18px;">${rankEmoji(j.rank)}</span>
        <span style="font-size:15px;font-weight:700;color:#111827;">${esc(j.title) || 'Poste non précisé'}</span>
      </div>
      <div style="color:#6B7280;font-size:13px;margin-bottom:8px;">${esc(j.company) || '—'}</div>
      <table style="width:100%;font-size:12px;border-collapse:collapse;margin-bottom:10px;">
        <tr>
          <td style="width:50%;padding:2px 0;"><span style="color:#6B7280;">📍 </span><strong>${esc(j.location) || '—'}</strong></td>
          <td style="width:50%;padding:2px 0;"><span style="color:#6B7280;">🏢 </span><strong>${esc(modeLabel(j))}</strong></td>
        </tr>
        <tr>
          <td style="padding:2px 0;"><strong style="color:${scoreColor}">${tierEmoji(j.tier)} ${j.score_100}/100</strong></td>
          <td style="padding:2px 0;color:#6B7280;">${esc(j.source)}</td>
        </tr>
      </table>
      <div style="font-size:11px;color:#6B7280;margin-bottom:10px;">🛠️ ${esc(skills)}</div>
      ${link}
    </div>`;
};

const stalenessWarning = runAgeHours > 72
  ? `<div style="background:#FEF2F2;border:1px solid #FCA5A5;border-radius:8px;padding:12px 20px;color:#991B1B;margin-bottom:16px;">⚠️ Données du run complété il y a ${Math.round(runAgeHours)}h (run ${runId}). Un run plus récent est peut-être disponible.</div>`
  : '';

const jobsHtml = topJobs.length > 0
  ? topJobs.map(jobCard).join('')
  : `<div style="background:#FEF3C7;border:1px solid #F59E0B;border-radius:8px;padding:16px 20px;color:#92400E;">Aucune offre pertinente trouvée dans ce run pipeline.</div>`;

const html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Digest Emploi — ${formattedDate}</title>
</head>
<body style="margin:0;padding:0;background:#F3F4F6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background:#F3F4F6;">
    <tr><td align="center" style="padding:32px 16px;">
      <table width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;">
        <tr><td style="background:#1E3A5F;border-radius:8px 8px 0 0;padding:26px 32px;">
          <h1 style="margin:0;color:#fff;font-size:21px;font-weight:700;">📊 Digest Emploi Hebdomadaire</h1>
          <p style="margin:6px 0 0;color:#93C5FD;font-size:13px;">${formattedDate} · Run du ${runCompletedAt} UTC</p>
        </td></tr>
        <tr><td style="background:#F9FAFB;padding:24px 32px;">
          ${stalenessWarning}
          <p style="font-size:13px;color:#6B7280;margin-top:0;">Les ${topJobs.length} meilleures offres toutes localisations confondues, classées par score personnalisé décroissant. Les notifications Discord en temps réel restent organisées par zone géographique préférée — ce récapitulatif hebdomadaire est volontairement plus large. Données du pipeline run <code>${runId}...</code></p>
          <h2 style="margin:24px 0 12px;font-size:17px;font-weight:700;color:#1E3A5F;border-bottom:2px solid #1E3A5F;padding-bottom:6px;">📊 Top ${topJobs.length} — Toutes localisations</h2>
          ${jobsHtml}
        </td></tr>
        <tr><td style="background:#E5E7EB;border-radius:0 0 8px 8px;padding:14px 32px;">
          <p style="margin:0;font-size:11px;color:#6B7280;">Find Your Job With AI · ${new Date().toISOString().slice(0, 10)} · Run ${runId}... · ${topJobs.length} offres</p>
        </td></tr>
      </table>
    </td></tr>
  </table>
</body>
</html>`;

const subject = `📊 Digest Emploi — Top ${topJobs.length} cette semaine — ${formattedDate}`;

return [{ json: { subject, html_body: html, digest_key: digestKey, job_count: topJobs.length } }];

const data = $input.first().json;
const digestKey = data.digest_key;
if (digestKey) {
  const sd = $getWorkflowStaticData('global');
  if (sd.sentDigests) {
    sd.sentDigests[digestKey] = { status: 'sent', ts: new Date().toISOString() };
  }
}
return [{ json: { done: true, digest_key: digestKey, job_count: data.job_count } }];
